import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"LSP Features","description":"","frontmatter":{},"headers":[],"relativePath":"lsp/index.md","filePath":"lsp/index.md"}'),n={name:"lsp/index.md"};function o(d,e,l,r,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="lsp-features" tabindex="-1">LSP Features <a class="header-anchor" href="#lsp-features" aria-label="Permalink to &quot;LSP Features&quot;">​</a></h1><p>Standard Language Server Protocol features. None of these need configuration except where noted.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th></tr></thead><tbody><tr><td>Hover</td><td>Kind, type, and documentation of the symbol under the cursor</td></tr><tr><td>Go to definition</td><td>Jumps to the declaration</td></tr><tr><td>Find references</td><td>All uses of a symbol, including macros (<code>`WIDTH</code> at its <code>`define</code> or any use)</td></tr><tr><td>Rename</td><td>Renames a symbol across all references. Keywords cannot be renamed</td></tr><tr><td>Completion</td><td>Context-aware suggestions; see <a href="./completion">Completion</a></td></tr><tr><td>Signature help</td><td>Parameters while typing a call or a <code>#(...)</code> list; triggers on <code>(</code> and <code>,</code></td></tr><tr><td>Workspace symbols</td><td>Case-insensitive substring search over modules and classes. Needs <code>[design].vcode</code></td></tr><tr><td>Inlay hints</td><td>See below</td></tr><tr><td>Folding ranges</td><td>See <a href="./../folding/">Folding</a></td></tr></tbody></table><p>Cross-file features need the project indexed through a filelist. See <a href="./../design/">Design &amp; filelist</a>.</p><h2 id="inlay-hints" tabindex="-1">Inlay hints <a class="header-anchor" href="#inlay-hints" aria-label="Permalink to &quot;Inlay hints&quot;">​</a></h2><p>Inside each module instantiation, LazyVerilog shows the direction and type of every connected port, and an <code>N/M</code> count of connected ports at the opening parenthesis. Instances of modules from the filelist show hints once the background index is ready, so a file opened at startup may briefly show none.</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">[</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">inlay_hint</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">]</span></span>\n<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">enable </span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> true</span></span></code></pre></div><h2 id="folding-ranges" tabindex="-1">Folding ranges <a class="header-anchor" href="#folding-ranges" aria-label="Permalink to &quot;Folding ranges&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">[</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">folding</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">]</span></span>\n<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">enable </span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> true</span></span></code></pre></div><p>Neovim asks for folds and inlay hints on every edit. With <code>enable = false</code> the server answers with nothing. To stop the requests altogether, also set <code>folding = false</code> or <code>inlay_hints = false</code> in the Neovim <a href="./../installation/neovim"><code>setup()</code></a>.</p>',10)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
